108	                // metadata, and it always exists.
109	                stat: InodeStat::for_directory(mount_time, NEVER_EXPIRE_TTL),
110	                write_status: WriteStatus::Remote,
111	                kind_data: InodeKindData::default_for(InodeKind::Directory),
112	                lookup_count: 1,
113	                reader_count: 0,
114	            },
115	        );
116	
117	        let mut inodes = HashMap::new();
118	        inodes.insert(ROOT_INODE_NO, root);
119	
120	        let inner = SuperblockInner {
121	            bucket: bucket.to_owned(),
122	            inodes: RwLock::new(inodes),
123	            next_ino: AtomicU64::new(2),
124	            mount_time,
125	            config,
126	        };
127	        Self { inner: Arc::new(inner) }
128	    }
