130	    /// The kernel tells us when it removes a reference to an [InodeNo] from its internal caches via a forget call.
131	    /// The kernel may forget a number of references (`n`) in one forget message to our FUSE implementation.
132	    /// If the lookup count reaches zero, it is safe for the [Superblock] to delete the [Inode].
133	    pub fn forget(&self, ino: InodeNo, n: u64) {
134	        let inode = {
135	            if let Some(inode) = self.inner.inodes.read().unwrap().get(&ino).cloned() {
136	                inode
137	            } else {
138	                debug_assert!(
139	                    false,
140	                    "forget should not be called on inode already removed from superblock"
141	                );
142	                error!("forget called on inode {ino} already removed from the superblock");
143	                return;
144	            }
145	        };
146	
147	        logging::record_name(inode.name());
148	        let new_lookup_count = inode.dec_lookup_count(n);
149	        if new_lookup_count == 0 {
150	            // Safe to remove, kernel no longer has a reference to it.
151	            trace!(ino, "removing inode from superblock");
152	            let Some(inode) = self.inner.inodes.write().unwrap().remove(&ino) else {
153	                error!("forget called on inode {ino} already removed from the superblock");
154	                return;
155	            };
156	
157	            let parent = {
158	                if let Some(parent) = self.inner.inodes.read().unwrap().get(&inode.parent()).cloned() {
159	                    parent
160	                } else {
161	                    // Should be impossible for this to fail (VFS inodes reference their parent, so
162	                    // children need to be freed first), but let's not crash in a `forget` function...
163	                    debug_assert!(false, "children should be forgotten before parents");
164	                    return;
165	                }
166	            };
167	            let mut parent_state = parent.inner.sync.write().unwrap();
168	            let InodeKindData::Directory {
169	                children,
170	                writing_children,
171	                ..
172	            } = &mut parent_state.kind_data
173	            else {
174	                unreachable!("parent is always a directory");
175	            };
176	            if let Some(child) = children.get(inode.name()) {
177	                // Don't accidentally remove a newer inode (e.g. remote shadowing local)
178	                if child.ino() == ino {
179	                    children.remove(inode.name());
180	                }
181	            }
182	            writing_children.remove(&ino);
183	
184	            if let Ok(state) = inode.get_inode_state() {
185	                metrics::counter!(
186	                    "metadata_cache.inode_forgotten_before_expiry",
187	                    state.stat.is_valid().into(),
188	                );
189	            };
190	        }
191	    }
